import { z } from "zod";

/**
 * Contract for public/evals/index.json and public/evals/user-view/index.json, the small files the eval
 * view loads first. Generated by scripts/build-eval-index.mts from the POC's recorded runs using the POC's
 * own grading code (suiteReport). Every number shown as a result carries its split, the number of runs it
 * was computed over, and the suite(s) those runs came from, so no figure can be shown unlabelled.
 */

export const SPLITS = ["all", "dev", "test"] as const;
export const SplitSchema = z.enum(SPLITS);
export type Split = z.infer<typeof SplitSchema>;

/** One result number. `value` is null where suiteReport has nothing to measure (e.g. consistency with one repeat). */
export const LabelledNumberSchema = z
  .object({
    value: z.number().nullable(),
    split: SplitSchema,
    /** Runs the value was computed over: graded runs for key-graded metrics, finished runs for trace checks and timing, all for cost, runs carrying a judge panel for judgePass. */
    runs: z.number().int().nonnegative(),
    /** Suite (arena) ids whose runs were pooled. */
    suite: z.array(z.string().min(1)).min(1),
  })
  .strict();
export type LabelledNumber = z.infer<typeof LabelledNumberSchema>;

/** The same metric for all eval weeks, the dev weeks and the held-out test weeks; each slot names its own split. */
export const SplitNumbersSchema = z
  .object({ all: LabelledNumberSchema, dev: LabelledNumberSchema, test: LabelledNumberSchema })
  .strict()
  .superRefine((v, ctx) => {
    for (const s of SPLITS)
      if (v[s].split !== s) ctx.addIssue({ code: "custom", path: [s, "split"], message: `slot "${s}" holds a "${v[s].split}" number` });
  });

/** Metrics taken from suiteReport's per-setup output: `metrics.*`, `score`, `costPerRun` and `msMean` (as seconds). */
export const METRICS = [
  "recall",
  "precision",
  "trapAvoidance",
  "datesRight",
  "tierRight",
  "ownerRight",
  "judgePass",
  "consistency",
  "traceChecks",
  "score",
  "costPerRunUsd",
  "secondsPerRun",
] as const;
export type Metric = (typeof METRICS)[number];

const RunCountsSchema = z.object({
  total: z.number().int().nonnegative(),
  finished: z.number().int().nonnegative(),
  graded: z.number().int().nonnegative(),
});

/** One setup's pooled results over one or more suites (the live setup, the baseline). */
export const SetupResultSchema = z.object({
  setup: z.string().min(1),
  label: z.string(),
  suite: z.array(z.string().min(1)).min(1),
  runCounts: z.object({ all: RunCountsSchema, dev: RunCountsSchema, test: RunCountsSchema }),
  ...(Object.fromEntries(METRICS.map((m) => [m, SplitNumbersSchema])) as Record<Metric, typeof SplitNumbersSchema>),
});
export type SetupResult = z.infer<typeof SetupResultSchema>;

export const SuiteSummarySchema = z.object({
  id: z.string().min(1),
  createdAt: z.string(),
  runs: z.number().int().nonnegative(),
  traces: z.number().int().nonnegative(),
  failed: z.number().int().nonnegative(),
  /** Run records arenaRuns() skipped and the bundle kept anyway, flagged `superseded: true` in runs.jsonl.gz. */
  superseded: z.number().int().nonnegative(),
  configHashes: z.array(z.string()),
  weeks: z.array(z.object({ id: z.string(), split: z.enum(["dev", "test"]) })),
  evalsets: z.array(z.string()),
  setups: z.array(
    z.object({
      key: z.string(),
      label: z.string(),
      runs: z.number().int().nonnegative(),
      finished: z.number().int().nonnegative(),
      failed: z.number().int().nonnegative(),
      graded: z.number().int().nonnegative(),
    }),
  ),
});

export const SetupInfoSchema = z.object({
  key: z.string(),
  label: z.string(),
  model: z.string(),
  modelLabel: z.string(),
  method: z.string(),
  promptSet: z.string().nullable(),
  suites: z.array(z.string()),
});

/** One improvement iteration. `07-next` has evidence only (error-analysis.json), so its record fields are null. */
export const IterationSummarySchema = z.object({
  id: z.string(),
  title: z.string().nullable(),
  date: z.string().nullable(),
  decision: z.string().nullable(),
  setup: z.string().nullable(),
  comparedTo: z.string().nullable(),
  suite: z.string().nullable(),
  /** iteration.yaml → results, as recorded by the POC's scripts/iteration.mts (suite-1 figures for that iteration). */
  results: z.record(z.string(), z.unknown()).nullable(),
  evidenceOnly: z.boolean(),
});

export const EvalIndexSchema = z.object({
  schemaVersion: z.literal(1),
  /** The poc commit the bundle was built from. */
  source: z.object({ branch: z.string(), commit: z.string().regex(/^[0-9a-f]{40}$/) }),
  suites: z.array(SuiteSummarySchema),
  setups: z.array(SetupInfoSchema),
  iterations: z.array(IterationSummarySchema),
  live: SetupResultSchema,
  baseline: SetupResultSchema,
  counts: z.object({
    suites: z.number().int().nonnegative(),
    runs: z.number().int().nonnegative(),
    traces: z.number().int().nonnegative(),
    userViewRuns: z.number().int().nonnegative(),
    iterations: z.number().int().nonnegative(),
  }),
});
export type EvalIndex = z.infer<typeof EvalIndexSchema>;

/** public/evals/user-view/index.json: every example run, failed ones included. */
export const UserViewIndexSchema = z.array(
  z.object({
    id: z.string(),
    profileId: z.string(),
    window: z.object({ start: z.string(), end: z.string() }),
    status: z.enum(["done", "error", "running"]),
    /** Action items in the report; null when the run produced none (failed runs). */
    items: z.number().int().nonnegative().nullable(),
    setup: z.string().nullable(),
  }),
);
export type UserViewIndex = z.infer<typeof UserViewIndexSchema>;
